let coinGlassPending, coinGlassCached;
async function coinGlassReport(env) {
  if (!env.COINGLASS_API_KEY) return Response.json({status:'unconfigured'},{status:503});
  if (coinGlassCached && Date.now()-coinGlassCached.time<60000) return Response.json(coinGlassCached);
  async function read(path) {
    const res=await fetch('https://open-api-v4.coinglass.com/api/futures/liquidation/'+path,{
      headers:{'CG-API-KEY':env.COINGLASS_API_KEY},signal:AbortSignal.timeout(7500)
    });
    const payload=await res.json().catch(()=>({}));
    if(!res.ok || String(payload.code)!=='0'){
      const msg=String(payload.msg||payload.message||'');
      const reason=/plan|subscription|upgrade|package/i.test(msg)?'subscription':/invalid.*key|key.*invalid/i.test(msg)?'invalid_key':/rate|frequency/i.test(msg)?'rate_limit':/expired/i.test(msg)?'expired':/permission|access|authorize/i.test(msg)?'access_denied':'upstream_error';
      throw Object.assign(Error(reason),{detail:{reason,http:res.status,code:/^[0-9-]{1,8}$/.test(String(payload.code))?String(payload.code):null}});
    }
    if(String(payload.code)!=='0'||!Array.isArray(payload.data)||!payload.data.length) throw Error('Missing observations');
    return payload.data;
  }
  async function collect() {
    const periods=['1h','4h','12h','24h'];
    const coins=await read('coin-list?exchange=all');
    if(new Set(coins.map(row=>row.symbol)).size!==coins.length) throw Error('Duplicate symbols');
    const windows=periods.map(period=>{
      const sums={period,total:0,long:0,short:0};
      for(const row of coins){
        for(const [field,prefix] of [['total',''],['long','long_'],['short','short_']]){
          const value=row[prefix+'liquidation_usd_'+period];
          if(!Number.isFinite(value)||value<0) throw Error('Invalid observation');
          sums[field]+=value;
        }
      }
      return sums;
    });
    coinGlassCached={time:Date.now(),windows,coins:coins.map(c=>({symbol:c.symbol,amount:c.liquidation_usd_24h,long:c.long_liquidation_usd_24h})).filter(c=>typeof c.symbol==='string'&&Number.isFinite(c.amount)&&c.amount>0).sort((a,b)=>b.amount-a.amount)};
    return coinGlassCached;
  }
  try {
    if(!coinGlassPending) coinGlassPending=collect().finally(()=>{coinGlassPending=null;});
    return Response.json(await coinGlassPending);
  } catch(error) {return Response.json({status:'unavailable',...(error.detail||{reason:error.name==='TimeoutError'?'timeout':'upstream_unreachable'})},{status:503,headers:{'cache-control':'no-store'}});}
}
